;==============================================================================
;  SNIPPET: Sprite animation (switch the sprite pointer)
;  Category: Sprites                     Type: program (open as a new file)
;------------------------------------------------------------------------------
;  An animation is a series of sprite images (frames) in memory, one after
;  the other in 64-byte blocks. To animate, only the sprite pointer is
;  changed - no copying of graphics.
;
;  Here: 4 frames of a pulsing ball, every ANIM_SPEED frames the next one.
;  The frames are generated by ACME (a circle with growing radius), so the
;  example needs no graphics files. Put your own frames there with
;  !byte lines or  !bin "frames.bin"  (a sprite editor exports 64 bytes
;  per frame).
;==============================================================================

FRAMES      = $2000             ; frame n at $2000 + n * 64
NUM_FRAMES  = 4
ANIM_SPEED  = 6                 ; screen frames per animation frame

        * = $0801
        !word +, 10
        !byte $9e
        !text "2061"
        !byte 0
+       !word 0

start
        lda #0
        sta $d020
        sta $d021
        jsr $e544
        lda #160
        sta $d000
        lda #130
        sta $d001
        lda #13
        sta $d027
        lda #1
        sta $d015
        sta $d017               ; double height
        sta $d01d               ; double width

loop
-       lda $d012               ; once per frame
        cmp #$fb
        bne -
-       lda $d012
        cmp #$fb
        beq -
        dec delay
        bne +
        lda #ANIM_SPEED
        sta delay
        ldx frame               ; next frame
        inx
        cpx #NUM_FRAMES
        bne ++
        ldx #0
++      stx frame
        txa
        clc
        adc #FRAMES / 64        ; pointer = first block + frame number
        sta $07f8
+
        jsr $ffe4
        cmp #' '
        beq +
        jmp loop
+       lda #0
        sta $d015
        lda #14
        sta $d020
        lda #6
        sta $d021
        jmp $e544

frame   !byte 0
delay   !byte 1

;------------------------------------------------------------------------------
; 4 frames: filled circles with radius 4, 6, 8, 10 (generated by ACME)
;------------------------------------------------------------------------------
        * = FRAMES
        !for f, 0, NUM_FRAMES - 1 {
            !set r = 4 + f * 2              ; radius 4, 6, 8, 10
            !for y, 0, 20 {
                !for b, 0, 2 {
                    !set bits = 0
                    !for x, 0, 7 {
                        !set dx = b * 8 + x - 11.5
                        !set dy = y - 10
                        !if dx * dx + dy * dy < r * r { !set bits = bits | (128 >> x) }
                    }
                    !byte bits
                }
            }
            !byte 0
        }
